// Use opens a resource via opener, retrying on TransientError, then calls
// Frob(input) on the resource, recovering from any panic (calling Defrob
// when the panic is a FrobError), and always closes the resource exactly
// once if it was successfully opened.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	for {
		r, err := opener()
		if err == nil {
			resource = r
			break
		}
		if _, ok := err.(TransientError); ok {
			continue
		}
		return err
	}
	defer resource.Close()

	return frob(resource, input)
}

func frob(resource Resource, input string) (err error) {
	defer func() {
		if r := recover(); r != nil {
			if frobErr, ok := r.(FrobError); ok {
				resource.Defrob(frobErr.defrobTag)
				err = frobErr
				return
			}
			err = r.(error)
		}
	}()
	resource.Frob(input)
	return nil
}
"}

